// See zonos3-languages.h.
#include "zonos3-languages.h"

#include "json.hpp"
#include "zonos3-languages-json.h" // generated by CMake: zonos3_languages_json[], zonos3_languages_json_len

namespace {

struct registry {
    std::vector<zonos3_server_language> server;
    std::vector<std::string> codes;
    std::vector<std::pair<std::string, std::string>> espeak;
};

const registry & languages() {
    static const registry r = [] {
        // ordered_json keeps the espeak object's key order.
        const auto doc = nlohmann::ordered_json::parse(
            std::string((const char *) zonos3_languages_json, zonos3_languages_json_len));
        registry out;
        for (const auto & row : doc.at("server")) {
            out.server.push_back({row.at("code").get<std::string>(), row.at("nemo").get<std::string>(),
                                  row.at("lexicon").get<std::string>()});
            out.codes.push_back(out.server.back().code);
        }
        for (const auto & [code, voice] : doc.at("espeak").items())
            out.espeak.emplace_back(code, voice.get<std::string>());
        return out;
    }();
    return r;
}

} // namespace

const std::vector<zonos3_server_language> & zonos3_server_languages() {
    return languages().server;
}
const std::vector<std::string> & zonos3_server_language_codes() {
    return languages().codes;
}
const std::vector<std::pair<std::string, std::string>> & zonos3_espeak_voices() {
    return languages().espeak;
}
